ruleToc.chapterList:
@js:
// 生成默认标题，最后兜底用，希望永远用不上
function buildDefaultTitle(url, index, maxPerPage = 60) {
    const pageNo = url.match(/_(\d+)/)?.[1] ?? 1;
    const num = (pageNo - 1) * maxPerPage + index + 1;
    return "第" + num + "章";
}

// 正则提取css ::after content
function getCssAfterTitle(pClass, sourceHtml) {
    if(!pClass || pClass?.isEmpty()) return "";
    const htmlStr = String(sourceHtml);
    const reg = new RegExp(pClass + "::after\\s*\\{[^}]*content\\s*:\\s*['\"](.*?)['\"]", "is");
    const match = htmlStr.match(reg);
    if (match) {
        let txt = match[1];
        txt = txt.replace(/\\(.)/g, "$1");
        return txt;
    }
    return "";
}

